// Kiểm tra dữ liệu WordPress gửi sang và chuẩn bị câu trả lời.
// Mọi tín hiệu kiểm tra được giữ lại trong output để xem ở tab Executions.
const receivedAt = new Date().toISOString();
const input = $input.first().json;
const body = input.body ?? {};
const headers = input.headers ?? {};
const executionId = $execution.id;
const requestId = body.request_id ?? headers['x-socialsync-request-id'] ?? null;

const trace = {
  received_at: receivedAt,
  request_id: requestId,
  plugin_version: headers['x-socialsync-version'] ?? null,
  content_type: headers['content-type'] ?? null,
  event: body.event ?? null,
};

if (body.event === 'test') {
  return [{ json: {
    http_status: 200,
    response: { ok: true, test: true, execution_id: executionId, request_id: requestId, received_at: receivedAt },
    trace,
    data: body,
  } }];
}

const problems = [];
const need = (cond, msg) => { if (!cond) problems.push(msg); };
const jobs = Array.isArray(body.jobs) ? body.jobs : [];

need(body.event === 'post_published', `event không hợp lệ: ${JSON.stringify(body.event)}`);
need(Number.isInteger(body.post_id) && body.post_id > 0, 'thiếu hoặc sai post_id');
need(['post', 'product'].includes(body.post_type), `post_type không hỗ trợ: ${JSON.stringify(body.post_type)}`);
need(typeof body.title === 'string' && body.title.trim() !== '', 'thiếu title');
need(typeof body.source_url === 'string' && /^https?:\/\//.test(body.source_url), 'thiếu hoặc sai source_url');
need(typeof body.callback_url === 'string' && /^https?:\/\//.test(body.callback_url), 'thiếu hoặc sai callback_url');
need(jobs.length > 0, 'không có lượt đồng bộ nào (jobs rỗng)');
for (const j of jobs) {
  need(Number.isInteger(j.job_id) && (j.job_id > 0 || body.dry_run === true), `lượt thiếu job_id: ${JSON.stringify(j)}`);
  need(['facebook', 'pinterest'].includes(j.channel), `kênh không hỗ trợ: ${JSON.stringify(j.channel)}`);
}

const signals = {
  post_type: body.post_type ?? null,
  channels: jobs.map(j => j.channel),
  delays_minutes: Object.fromEntries(jobs.map(j => [j.channel, j.delay_minutes ?? 0])),
  has_image: Boolean(body.image_url),
  image_size: body.image ? `${body.image.width}x${body.image.height}` : null,
  title_chars: (body.title ?? '').length,
  content_chars: (body.content_text ?? '').length,
  excerpt_chars: (body.excerpt ?? '').length,
  categories: body.categories ?? [],
  has_price: Boolean(body.price && body.price.price),
  pinterest_will_skip: jobs.some(j => j.channel === 'pinterest') && !body.image_url,
  dry_run: body.dry_run === true,
  approval_required: body.approval_required === true,
  planned: Object.fromEntries(jobs.map(j => [j.channel, j.scheduled_at ?? null])),
};

if (problems.length) {
  return [{ json: {
    http_status: 422,
    response: { ok: false, execution_id: executionId, request_id: requestId, error: problems.join('; ') },
    problems,
    signals,
    trace,
    data: body,
  } }];
}

return [{ json: {
  http_status: 202,
  response: {
    ok: true,
    execution_id: executionId,
    request_id: requestId,
    received_at: receivedAt,
    accepted_jobs: jobs.map(j => j.job_id),
  },
  signals,
  trace,
  data: body,
} }];

// Nấc 3: tách mỗi lượt (kênh) thành một item và dựng nội dung theo MẪU CỐ ĐỊNH (chưa dùng AI).
// Chỉ chạy tiếp khi bước kiểm tra đã nhận bài (HTTP 202). Gói test hoặc dữ liệu lỗi dừng ở đây.
const CONFIG = {
  fb_page_id: '273106486233478',   // Fanpage Mint Shop - facebook.com/myphamcuatrang (ID công khai, không phải bí mật)
  graph_version: 'v21.0',
  utm_campaign: 'socialsync',
  fb_summary_max: 400,
  pin_title_max: 100,
  pin_description_max: 400,
};

const checked = $('Kiểm tra dữ liệu').first().json;
if (checked.http_status !== 202) {
  return [];
}
const d = checked.data;

// Lỗi giả lập CÓ CHỦ Ý để kiểm tra luồng "SocialSync - Báo lỗi": chỉ xảy ra khi tiêu đề chứa đúng chuỗi dưới.
if (String(d.title ?? '').includes('[socialsync-thu-loi]')) {
  throw new Error('Lỗi giả lập để kiểm tra luồng báo lỗi (tiêu đề chứa [socialsync-thu-loi])');
}

// Môi trường Code của n8n 2.x không có đối tượng URL (đo 2026-11-19: ReferenceError: URL is not defined),
// nên gắn tham số UTM bằng xử lý chuỗi.
const withUtm = (url, source) => {
  const hashAt = url.indexOf('#');
  const base = hashAt === -1 ? url : url.slice(0, hashAt);
  const hash = hashAt === -1 ? '' : url.slice(hashAt);
  const utm = `utm_source=${encodeURIComponent(source)}&utm_medium=social&utm_campaign=${encodeURIComponent(CONFIG.utm_campaign)}`;
  return base + (base.includes('?') ? '&' : '?') + utm + hash;
};

// Cắt ở ranh giới câu nếu được, nếu không thì ở ranh giới từ. Không cắt giữa từ.
const clip = (text, max) => {
  const t = String(text ?? '').replace(/\s+/g, ' ').trim();
  if (t.length <= max) return t;
  const cut = t.slice(0, max);
  const sentenceEnd = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  if (sentenceEnd > max * 0.5) return cut.slice(0, sentenceEnd + 1);
  return cut.slice(0, Math.max(cut.lastIndexOf(' '), 1)) + '…';
};

const summary = clip(d.excerpt || d.content_text, CONFIG.fb_summary_max);
const priceLine = d.price && d.price.price_text ? `Giá: ${d.price.price_text}` : null;
const now = Date.now();

const items = d.jobs.map(job => {
  const link = withUtm(d.source_url, job.channel);
  let content;
  let facebook = null;

  if (job.channel === 'facebook') {
    const message = [d.title, summary, priceLine, `👉 Xem chi tiết: ${link}`].filter(Boolean).join('\n\n');
    content = { kind: d.image_url ? 'photo' : 'link', message, link, image_url: d.image_url || null };
    facebook = d.image_url
      ? { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/photos`, body: { url: d.image_url, caption: message, published: true } }
      : { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/feed`, body: { message, link } };
  } else {
    content = {
      title: clip(d.title, CONFIG.pin_title_max),
      description: clip([summary, priceLine].filter(Boolean).join(' '), CONFIG.pin_description_max),
      alt_text: d.image_alt || d.title,
      link,
      image_url: d.image_url || null,
      board: d.pinterest_board || null,
    };
  }

  // Giờ đăng do bộ xếp lịch của WordPress chọn (khung giờ, số bài/ngày, khoảng cách). Không có thì dùng số phút trễ.
  const planned = job.scheduled_at ? Date.parse(job.scheduled_at) : NaN;
  const atMs = Number.isFinite(planned) ? Math.max(now, planned) : now + Math.max(0, Math.round(Number(job.delay_minutes ?? 0) * 60)) * 1000;
  const delaySeconds = Math.round((atMs - now) / 1000);
  return {
    json: {
      job_id: job.job_id,
      channel: job.channel,
      post_id: d.post_id,
      post_type: d.post_type,
      title: d.title,
      request_id: d.request_id ?? null,
      has_image: Boolean(d.image_url),
      delay_seconds: delaySeconds,
      scheduled_at: new Date(atMs).toISOString(),
      callback_job_url: `${d.callback_url}/${job.job_id}`,
      content_source: 'template',
      content_source_reason: 'Chưa bật AI, dùng mẫu cố định',
      content,
      facebook,
    },
  };
});

// Xếp lượt theo giờ đăng tăng dần. Vòng lặp phía sau xử lý lần lượt từng lượt và chờ tới đúng giờ
// của lượt đó, nên mỗi kênh đăng theo số phút trễ riêng của nó.
items.sort((a, b) => a.json.delay_seconds - b.json.delay_seconds);
console.log('[socialsync] Thứ tự đăng', JSON.stringify(items.map(i => ({ job_id: i.json.job_id, channel: i.json.channel, delay_seconds: i.json.delay_seconds, scheduled_at: i.json.scheduled_at }))));
return items;

// Chỉ đăng những lượt WordPress đã chấp nhận chuyển sang "scheduled".
// WordPress từ chối (ví dụ 409: lượt đã xử lý rồi) => dừng lượt đó, KHÔNG đăng, tránh đăng trùng.
const source = $('Gom lượt cần đăng').all();
const out = [];
$input.all().forEach((item, i) => {
  const s = source[i].json;
  const r = item.json;
  const ok = r.statusCode === 200 && r.body && r.body.ok === true;
  if (ok) {
    out.push({ json: { ...s, wp_scheduled: { statusCode: r.statusCode, body: r.body } }, pairedItem: { item: i } });
  } else {
    console.log(`[socialsync] Dừng lượt ${s.job_id} (${s.channel}): WordPress không chấp nhận`, JSON.stringify({ statusCode: r.statusCode ?? null, body: r.body ?? null, error: r.error ?? null }));
  }
});
return out;

// Đọc phản hồi của Facebook, chuẩn bị dữ liệu báo về WordPress.
// Mỗi bài chỉ gọi Facebook đúng 1 lần để tiết kiệm hạn mức API của app.
const s = $('Kênh Facebook?').item.json;
const r = $json;

let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* giữ nguyên chuỗi */ } }
const headers = r.headers ?? {};
// Facebook trả % hạn mức đã dùng trong các header này (app, Trang, doanh nghiệp).
const usage = {
  app: headers['x-app-usage'] ?? null,
  page: headers['x-page-usage'] ?? null,
  business: headers['x-business-use-case-usage'] ?? null,
};

let callback;
if (r.error && r.statusCode === undefined) {
  callback = { status: 'failed', error: `Không gọi được Facebook: ${r.error.message ?? JSON.stringify(r.error)}` };
} else if (r.statusCode >= 200 && r.statusCode < 300 && body && (body.post_id || body.id)) {
  const postId = body.post_id ?? body.id;
  callback = {
    status: 'published',
    remote_id: String(postId),
    remote_url: `https://www.facebook.com/${postId}`,
    // Bài đăng bởi app ở chế độ Live lên Trang công khai. Đã kiểm tra bằng cửa sổ ẩn danh ở lần test đầu.
    visibility: 'public',
    published_at: new Date().toISOString(),
  };
} else {
  const e = (body && body.error) || {};
  const rateLimited = [4, 17, 32, 613, 80001].includes(Number(e.code));
  callback = {
    status: 'failed',
    error: `Facebook từ chối (HTTP ${r.statusCode}${e.code ? `, mã ${e.code}` : ''}${e.error_subcode ? `/${e.error_subcode}` : ''}${rateLimited ? ', HẾT HẠN MỨC GỌI API' : ''}): ${e.message ?? JSON.stringify(body)}${e.fbtrace_id ? ` [fbtrace_id ${e.fbtrace_id}]` : ''}`,
  };
}
callback.execution_id = $execution.id;

return { json: { ...s, callback, facebook_result: { statusCode: r.statusCode ?? null, body, usage } } };

// Đọc phản hồi của Make (scenario "SocialSync - Pinterest"), chuẩn bị dữ liệu báo về WordPress.
// Khối "Webhook response" bên Make trả: {"ok": true, "pin_id": "...", "request_id": "...", "job_id": ...}
const s = $('Pinterest: có ảnh?').item.json;
const r = $json;

let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* giữ nguyên chuỗi */ } }
const snippet = (v) => {
  const t = typeof v === 'string' ? v : JSON.stringify(v);
  return t && t.length > 300 ? t.slice(0, 300) + '…' : t;
};
const pinId = body && typeof body === 'object' ? String(body.pin_id ?? '').trim() : '';

let callback;
if (r.error && r.statusCode === undefined) {
  const msg = r.error.message ?? JSON.stringify(r.error);
  const hint = /MAKE_PINTEREST_WEBHOOK|invalid url/i.test(msg)
    ? ' (chưa có MAKE_PINTEREST_WEBHOOK trong .env, hoặc chưa chạy lại scripts/n8n-nap-luong.ps1)'
    : '';
  callback = { status: 'failed', error: `Không gọi được Make: ${msg}${hint}` };
} else if (r.statusCode === 200 && /^\d+$/.test(pinId)) {
  callback = {
    status: 'published',
    remote_id: pinId,
    remote_url: `https://www.pinterest.com/pin/${pinId}/`,
    // Make dùng app Pinterest đã được duyệt đầy đủ. Pin thử đầu tiên xem được khi chưa đăng nhập (2026-11-19).
    visibility: 'public',
    published_at: new Date().toISOString(),
  };
} else {
  let hint = '';
  if (typeof body === 'string' && body.trim() === 'Accepted') {
    hint = ' (Make chưa trả kết quả: scenario đang TẮT, hoặc thiếu khối "Webhook response")';
  } else if (r.statusCode === 200) {
    hint = ' (Make trả về nhưng không có pin_id dạng số: kiểm tra nội dung khối "Webhook response")';
  }
  callback = { status: 'failed', error: `Make/Pinterest không tạo được Pin (HTTP ${r.statusCode}): ${snippet(body)}${hint}` };
}
callback.execution_id = $execution.id;

return { json: { ...s, callback, pinterest_result: { statusCode: r.statusCode ?? null, body, request_id_echo: body && body.request_id ? body.request_id : null } } };

// Pinterest bắt buộc mỗi Pin có ảnh.
const s = $json;
return { json: { ...s, callback: { status: 'skipped', error: 'Bài không có ảnh đại diện, Pinterest bắt buộc có ảnh', execution_id: $execution.id } } };

// Chạy một lần khi vòng lặp xong mọi kênh: gom kết quả WordPress trả về cho từng lượt.
const results = $input.all().map(i => ({
  statusCode: i.json.statusCode ?? null,
  job_id: i.json.body?.job_id ?? null,
  status_before: i.json.body?.status_before ?? null,
  status_after: i.json.body?.status_after ?? null,
  error: i.json.body?.error ?? i.json.error?.message ?? null,
}));
console.log('[socialsync] Tổng kết', JSON.stringify(results));
return [{ json: { total: results.length, all_ok: results.every(r => r.statusCode === 200), results } }];

// Dựng MỘT yêu cầu gửi Claude cho cả bài: Claude viết nội dung cho mọi kênh trong một lần gọi.
// Giá và link KHÔNG để AI viết: bước sau tự gắn từ dữ liệu WordPress, nên không thể bị bịa.
const AI = {
  model: 'claude-opus-5-5',
  effort: 'medium',
  max_tokens: 8000,
  content_max_chars: 4000,
};

const items = $input.all();
const d = $('Kiểm tra dữ liệu').first().json.data;
const channels = items.map(i => i.json.channel);

const SYSTEM = [
  'Bạn là biên tập viên mạng xã hội cho một doanh nghiệp ở Việt Nam bán sản phẩm sức khỏe và làm đẹp.',
  'Với mỗi bài vừa đăng trên website, bạn làm hai việc: phân loại bài, rồi viết nội dung đăng Facebook Fanpage và Pinterest.',
  '',
  'Bước 1 – Phân loại (phan_loai.loai):',
  '- E (Kiến thức): kiến thức sức khỏe, dinh dưỡng, làm đẹp, mẹo; không giới thiệu một sản phẩm cụ thể.',
  '- P (Sản phẩm): giới thiệu hoặc mời mua một sản phẩm cụ thể, hoặc nêu công dụng của một sản phẩm cụ thể.',
  '- N (Tin thương hiệu): sự kiện, hoạt động xã hội, hợp tác, báo chí nói về công ty.',
  '- X (Không đồng bộ): tin nội bộ, thông báo chính sách hoặc chương trình bán hàng cho đại lý/nhà thuốc, văn bản hành chính, bài viết bằng tiếng nước ngoài.',
  '- Không chắc giữa hai loại thì chọn loại thận trọng hơn theo thứ tự X, P, N, E và nói rõ trong ly_do (một câu ngắn).',
  '- nhom_nhay_cam = true nếu bài nói về trẻ em, phụ nữ mang thai hoặc cho con bú, hoặc nhắc tên, hình ảnh bác sĩ, dược sĩ, cơ sở y tế.',
  '',
  'Bước 2 – Viết nội dung theo loại:',
  '- X: để trống mọi trường nội dung (chuỗi rỗng, mảng rỗng).',
  '- N: chỉ viết Facebook; các trường Pinterest để chuỗi rỗng.',
  '- E và P: viết cả hai kênh.',
  '',
  'Nguyên tắc nội dung:',
  '- Tiếng Việt có dấu, giọng thân thiện, rõ ràng, đáng tin.',
  '- Chỉ dùng thông tin có trong dữ liệu. Không bịa thành phần, công dụng, số liệu, khuyến mãi.',
  '- Không ghi giá, không ghi đường link, không viết câu khuyến cáo "Thực phẩm này không phải là thuốc…": hệ thống tự gắn các phần này.',
  '- Với sản phẩm sức khỏe: không khẳng định chữa, điều trị hay phòng ngừa bệnh; không so sánh với thuốc; không hứa hẹn kết quả (ví dụ "100%", "khỏi hẳn", "cam kết").',
  '- Không dùng so sánh nhất ("số 1", "tốt nhất", "duy nhất"), không nói về giảm cân, không mô tả kết quả trước–sau, không trích lời bác sĩ, dược sĩ hay người bệnh.',
  '- Câu mở không gán tình trạng bệnh cho người đọc (viết "Vì sao trẻ hay ốm vặt?" thay vì "Con bạn đang bị…").',
  '',
  'Facebook:',
  '- facebook.message: 60 đến 150 từ, câu đầu là câu mở gây chú ý, chia 2 đến 4 đoạn ngắn, tối đa 3 emoji. Không có hashtag trong message.',
  '- facebook.hashtags: 3 đến 5 hashtag liên quan, mỗi hashtag bắt đầu bằng #, viết liền không dấu.',
  '',
  'Pinterest:',
  '- pinterest.title: tối đa 90 ký tự, chứa từ khóa chính người dùng hay tìm.',
  '- pinterest.description: 150 đến 400 ký tự, viết như một mô tả tìm kiếm tự nhiên, có 2 đến 3 từ khóa, tối đa 3 hashtag.',
  '- pinterest.alt_text: tối đa 150 ký tự, mô tả chủ đề ảnh minh họa dựa trên tiêu đề, không bịa chi tiết hình ảnh.',
].join('\n');

const clipText = (t, max) => { const s = String(t ?? '').replace(/\s+/g, ' ').trim(); return s.length > max ? s.slice(0, max) + '…' : s; };
const post = {
  loai_noi_dung: d.post_type === 'product' ? 'Sản phẩm' : 'Bài viết',
  tieu_de: d.title,
  tom_tat: d.excerpt || null,
  noi_dung: clipText(d.content_text, AI.content_max_chars),
  danh_muc: d.categories ?? [],
  co_gia: Boolean(d.price && d.price.price_text),
  kenh_can_viet: channels,
};

const schema = {
  type: 'object',
  properties: {
    phan_loai: {
      type: 'object',
      properties: {
        loai: { type: 'string', enum: ['E', 'P', 'N', 'X'] },
        ly_do: { type: 'string' },
        nhom_nhay_cam: { type: 'boolean' },
      },
      required: ['loai', 'ly_do', 'nhom_nhay_cam'],
      additionalProperties: false,
    },
    facebook: {
      type: 'object',
      properties: {
        message: { type: 'string' },
        hashtags: { type: 'array', items: { type: 'string' } },
      },
      required: ['message', 'hashtags'],
      additionalProperties: false,
    },
    pinterest: {
      type: 'object',
      properties: {
        title: { type: 'string' },
        description: { type: 'string' },
        alt_text: { type: 'string' },
      },
      required: ['title', 'description', 'alt_text'],
      additionalProperties: false,
    },
  },
  required: ['phan_loai', 'facebook', 'pinterest'],
  additionalProperties: false,
};

const request_body = {
  model: AI.model,
  max_tokens: AI.max_tokens,
  // Nếu Claude Opus 5.5 từ chối vì bộ lọc an toàn, API tự chạy lại trên mô hình dự phòng (beta server-side-fallback).
  fallbacks: 'default',
  output_config: { effort: AI.effort, format: { type: 'json_schema', schema } },
  system: SYSTEM,
  messages: [{ role: 'user', content: 'Dữ liệu bài vừa đăng trên website (JSON):\n' + JSON.stringify(post, null, 2) }],
};

console.log('[socialsync] Gửi Claude', JSON.stringify({ request_id: d.request_id ?? null, post_id: d.post_id, model: AI.model, effort: AI.effort, channels, content_chars: post.noi_dung.length }));
return [{ json: { request_body, ai_started_ms: Date.now(), channels } }];

// Kiểm tra kết quả Claude, áp phân loại, quyết định từng lượt:
//   skip    – không đăng (bài loại X; tin thương hiệu N trên Pinterest)
//   review  – chờ người duyệt (chế độ Duyệt bắt buộc)
//   publish – đăng theo lịch luôn (chế độ Tự đăng)
//   preview – chạy thử, không đăng
// Nội dung AI không đạt kiểm tra thì GIỮ nội dung mẫu cố định và ghi lý do. Lỗi AI không chặn việc đăng.
const CONFIG = { fb_page_id: '273106486233478', graph_version: 'v21.0' };
// Các cụm từ quảng cáo sức khỏe bị cấm hoặc rủi ro cao. Câu khuyến cáo do hệ thống gắn được bỏ ra trước khi dò.
const BANNED = /(chữa\s+(khỏi|bệnh|trị|dứt)|điều\s+trị|đặc\s+trị|khỏi\s+hẳn|khỏi\s+bệnh|hết\s+bệnh|dứt\s+điểm|thay\s+thế\s+thuốc|100\s*%|cam\s+kết|thần\s+dược|số\s+1(?!\d)|tốt\s+nhất|duy\s+nhất|giảm\s+cân)/i;
const LABEL = { E: 'Kiến thức', P: 'Sản phẩm', N: 'Tin thương hiệu', X: 'Không đồng bộ' };

const req = $('AI: dựng yêu cầu').first().json;
const templ = $('Tách lượt và dựng nội dung').all();
const d = $('Kiểm tra dữ liệu').first().json.data;
const r = $input.first().json;
const aiMs = Date.now() - req.ai_started_ms;
const DISCLAIMER = String((d.rules && d.rules.product_disclaimer) || '').trim();

let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* giữ chuỗi */ } }
const usage = body && body.usage ? body.usage : {};
const modelUsed = body && body.model ? body.model : null;

const problems = [];
let ai = null;
if (r.error && r.statusCode === undefined) {
  problems.push(`không gọi được Claude: ${r.error.message ?? JSON.stringify(r.error)}`);
} else if (r.statusCode !== 200) {
  const e = (body && body.error) || {};
  problems.push(`Claude trả HTTP ${r.statusCode}${e.type ? ` (${e.type})` : ''}: ${e.message ?? String(JSON.stringify(body)).slice(0, 300)}${r.statusCode === 401 ? ' - kiểm tra ANTHROPIC_API_KEY trong .env rồi chạy lại scripts/n8n-nap-luong.ps1' : ''}`);
} else if (body.stop_reason !== 'end_turn') {
  problems.push(`Claude dừng với stop_reason=${body.stop_reason}${body.stop_details ? ` (${JSON.stringify(body.stop_details)})` : ''}`);
} else {
  const text = (body.content ?? []).filter(b => b.type === 'text').map(b => b.text).join('');
  try { ai = JSON.parse(text); } catch (e) { problems.push(`kết quả không phải JSON: ${text.slice(0, 200)}`); }
}

// Phân loại. Sản phẩm WooCommerce luôn là P (quy tắc cứng, không phụ thuộc AI).
let cls = ai && ai.phan_loai && LABEL[ai.phan_loai.loai] ? ai.phan_loai.loai : null;
let clsReason = ai && ai.phan_loai ? String(ai.phan_loai.ly_do || '') : '';
const sensitive = Boolean(ai && ai.phan_loai && ai.phan_loai.nhom_nhay_cam);
if (!cls) {
  cls = d.post_type === 'product' ? 'P' : 'E';
  clsReason = 'AI không phân loại được, dùng mặc định theo loại nội dung';
}
const aiCls = cls; // phân loại AI đề xuất, trước khi áp quy tắc sản phẩm
if (d.post_type === 'product' && cls !== 'P') {
  clsReason = `Sản phẩm WooCommerce luôn tính là Sản phẩm (AI đề xuất ${LABEL[cls]}: ${clsReason})`;
  cls = 'P';
}

const len = s => String(s ?? '').trim().length;
// Chỉ kiểm trường của những kênh có trong lượt này (Đồng bộ lại một kênh thì Claude chỉ viết cho kênh đó).
const channels = new Set(templ.map(t => t.json.channel));
if (ai && cls !== 'X') {
  const fb = ai.facebook ?? {};
  const pin = ai.pinterest ?? {};
  if (channels.has('facebook')) {
    if (len(fb.message) < 80 || len(fb.message) > 2000) problems.push(`facebook.message dài ${len(fb.message)} ký tự (cần 80-2000)`);
    if (!Array.isArray(fb.hashtags) || fb.hashtags.length > 8) problems.push('facebook.hashtags không hợp lệ');
  }
  if (cls !== 'N' && channels.has('pinterest')) {
    if (len(pin.title) < 10 || len(pin.title) > 100) problems.push(`pinterest.title dài ${len(pin.title)} ký tự (cần 10-100)`);
    if (len(pin.description) < 50 || len(pin.description) > 500) problems.push(`pinterest.description dài ${len(pin.description)} ký tự (cần 50-500)`);
    if (len(pin.alt_text) < 5 || len(pin.alt_text) > 500) problems.push(`pinterest.alt_text dài ${len(pin.alt_text)} ký tự`);
  }
  let allText = [fb.message, ...(fb.hashtags ?? []), pin.title, pin.description, pin.alt_text].join(' ');
  if (DISCLAIMER) allText = allText.split(DISCLAIMER).join(' ');
  const banned = allText.match(BANNED);
  if (banned) problems.push(`có cụm từ quảng cáo sức khỏe bị cấm: "${banned[0]}"`);
}

// Sản phẩm mà AI đề xuất Không đồng bộ: AI không viết nội dung (đúng theo phân loại của nó) nhưng sản phẩm luôn đăng,
// nên ghi lý do rõ ràng thay cho các lỗi "dài 0 ký tự".
if (ai && d.post_type === 'product' && aiCls === 'X' && problems.length) { // AI có viết đủ thì vẫn dùng
  problems.length = 0;
  problems.push('AI đề xuất Không đồng bộ nên không viết nội dung; sản phẩm luôn được đăng, dùng nội dung mẫu để người duyệt sửa');
}
console.log('[socialsync] Kiểm nội dung AI theo kênh', JSON.stringify({ channels: [...channels], ai_classification: aiCls, final_classification: cls, problems }));

const useAi = Boolean(ai) && problems.length === 0 && cls !== 'X';
const reason = useAi
  ? `Claude viết (${modelUsed}, 1 lần gọi cho ${templ.length} kênh, ${aiMs} ms)`
  : (cls === 'X' && ai ? `AI phân loại: Không đồng bộ` : `Dùng mẫu cố định vì AI không đạt: ${problems.join('; ')}`).slice(0, 250);
console.log('[socialsync] Kết quả AI', JSON.stringify({ use_ai: useAi, classification: cls, reason: clsReason, sensitive, problems, model: modelUsed, usage, ai_ms: aiMs, status: r.statusCode ?? null, stop_reason: body?.stop_reason ?? null, dry_run: d.dry_run === true, approval_required: d.approval_required === true }));

const priceLine = d.price && d.price.price_text ? `Giá: ${d.price.price_text}` : null;
const clipWords = (s, max) => { s = String(s).trim(); if (s.length <= max) return s; const c = s.slice(0, max); return c.slice(0, Math.max(c.lastIndexOf(' '), 1)) + '…'; };
const fbRequest = (message, link) => d.image_url
  ? { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/photos`, body: { url: d.image_url, caption: message, published: true } }
  : { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/feed`, body: { message, link } };

return templ.map((item, i) => {
  const s = item.json;
  const out = {
    ...s,
    classification: cls,
    content_source: useAi ? 'ai' : 'template',
    content_source_reason: reason,
    model: modelUsed,
    tokens_in: usage.input_tokens ?? null,
    tokens_out: usage.output_tokens ?? null,
    ai_ms: aiMs,
    ai_problems: problems,
  };

  let decision;
  let decisionReason = '';
  if (cls === 'X') {
    decision = 'skip';
    decisionReason = `AI phân loại bài là Không đồng bộ: ${clsReason}`;
  } else if (cls === 'N' && s.channel === 'pinterest') {
    decision = 'skip';
    decisionReason = 'Tin thương hiệu chỉ đăng Facebook, không đăng Pinterest';
  } else if (d.dry_run === true) {
    decision = 'preview';
  } else if (s.channel === 'pinterest' && !d.image_url) {
    // Báo ngay từ đầu (trước khi người duyệt mở bài): Pinterest bắt buộc mỗi Pin có ảnh.
    decision = 'skip';
    decisionReason = 'Bài không có ảnh đại diện nên không đăng được lên Pinterest (mỗi Pin bắt buộc có ảnh). Muốn đăng Pin: thêm ảnh đại diện cho bài rồi bấm Đồng bộ lại ở thẻ Pinterest của bài trong Trung tâm SocialSync.';
    console.log('[socialsync] Bỏ qua Pinterest vì bài không có ảnh', JSON.stringify({ post_id: d.post_id, job_id: s.job_id }));
  } else {
    decision = d.approval_required === true ? 'review' : 'publish';
  }

  const content = { ...s.content, classification_reason: clsReason, sensitive };
  if (s.channel === 'facebook') {
    if (useAi) {
      const tags = (ai.facebook.hashtags ?? []).map(t => String(t).trim()).filter(Boolean).map(t => t.startsWith('#') ? t : '#' + t).join(' ');
      content.message = [ai.facebook.message.trim(), cls === 'P' ? DISCLAIMER : null, priceLine, `👉 Xem chi tiết: ${s.content.link}`, tags].filter(Boolean).join('\n\n');
    } else if (cls === 'P' && DISCLAIMER) {
      content.message = String(s.content.message).replace('\n\n👉', `\n\n${DISCLAIMER}\n\n👉`);
    }
    out.facebook = fbRequest(content.message, s.content.link);
  } else {
    if (useAi) {
      content.title = ai.pinterest.title.trim().slice(0, 100);
      content.description = [ai.pinterest.description.trim(), priceLine].filter(Boolean).join(' ');
      content.alt_text = ai.pinterest.alt_text.trim().slice(0, 500);
    }
    if (cls === 'P' && DISCLAIMER) {
      content.description = clipWords(content.description, 500 - DISCLAIMER.length - 1) + ' ' + DISCLAIMER;
    }
    content.description = clipWords(content.description, 500);
  }
  out.content = content;
  out.decision = decision;
  out.decision_reason = decisionReason;
  return { json: out, pairedItem: { item: i } };
});

// Gom kết quả chạy thử của một bài (mọi kênh) thành một gói gửi về WordPress. Không đăng gì.
const d = $('Kiểm tra dữ liệu').first().json.data;
const items = $input.all().map(i => i.json);
const first = items[0] ?? {};
const DEC = { preview: 'Sẽ đăng (sau khi duyệt)', skip: 'Không đăng' };
const result = {
  classification_reason: first.content?.classification_reason ?? '',
  sensitive: Boolean(first.content?.sensitive),
  content_source: first.content_source ?? null,
  content_source_reason: first.content_source_reason ?? null,
  model: first.model ?? null,
  problems: first.ai_problems ?? [],
  decision_text: items.map(i => `${i.channel}: ${DEC[i.decision] ?? i.decision}${i.decision_reason ? ' (' + i.decision_reason + ')' : ''}`).join(' · '),
};
for (const i of items) {
  if (i.channel === 'facebook') result.facebook = { message: i.content.message, skip: i.decision === 'skip' ? i.decision_reason : null };
  if (i.channel === 'pinterest') result.pinterest = { title: i.content.title, description: i.content.description, alt_text: i.content.alt_text, board: i.content.board, skip: i.decision === 'skip' ? i.decision_reason : null };
}
console.log('[socialsync] Chạy thử xong', JSON.stringify({ preview_id: d.preview_id, classification: first.classification, decisions: result.decision_text }));
return [{ json: {
  callback_url: d.callback_url,
  request_id: d.request_id ?? null,
  payload: { ok: true, classification: first.classification ?? null, tokens_in: first.tokens_in ?? null, tokens_out: first.tokens_out ?? null, ai_ms: first.ai_ms ?? null, result },
} }];

// Điểm gặp của hai đường: (1) Tự đăng – lượt vừa được AI viết; (2) lệnh đăng sau khi người duyệt bấm Duyệt.
const items = $input.all();
console.log('[socialsync] Lượt cần đăng', JSON.stringify(items.map(i => ({ job_id: i.json.job_id, channel: i.json.channel, scheduled_at: i.json.scheduled_at, approved: i.json.approved === true }))));
return items.map((it, i) => ({ json: it.json, pairedItem: { item: i } }));

// Lệnh đăng từ WordPress sau khi người duyệt bấm Duyệt (nội dung có thể đã được sửa).
// Dựng lại từng lượt đúng dạng mà phần đăng bài phía sau cần.
const CONFIG = { fb_page_id: '273106486233478', graph_version: 'v21.0' };
const body = $input.first().json.body ?? {};
const jobs = Array.isArray(body.jobs) ? body.jobs : [];
if (body.event !== 'approved' || !jobs.length || !body.callback_url) {
  throw new Error(`Lệnh đăng không hợp lệ: event=${body.event}, jobs=${jobs.length}, callback_url=${Boolean(body.callback_url)}`);
}
const now = Date.now();
const items = jobs.map(job => {
  const content = { ...(job.content ?? {}) };
  content.image_url = content.image_url || body.image_url || null;
  const planned = Date.parse(job.scheduled_at);
  const atMs = Number.isFinite(planned) ? Math.max(now, planned) : now;
  let facebook = null;
  if (job.channel === 'facebook') {
    facebook = content.image_url
      ? { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/photos`, body: { url: content.image_url, caption: content.message, published: true } }
      : { url: `https://graph.facebook.com/${CONFIG.graph_version}/${CONFIG.fb_page_id}/feed`, body: { message: content.message, link: content.link } };
  }
  return { json: {
    job_id: job.job_id,
    channel: job.channel,
    post_id: body.post_id,
    post_type: body.post_type,
    title: body.title,
    request_id: body.request_id ?? null,
    has_image: Boolean(content.image_url),
    delay_seconds: Math.round((atMs - now) / 1000),
    scheduled_at: new Date(atMs).toISOString(),
    callback_job_url: `${body.callback_url}/${job.job_id}`,
    content_source: job.content_source ?? null,
    content_source_reason: job.content_source_reason ?? null,
    model: job.model ?? null,
    tokens_in: job.tokens_in ?? null,
    tokens_out: job.tokens_out ?? null,
    ai_ms: job.ai_ms ?? null,
    classification: job.classification ?? null,
    content,
    facebook,
    decision: 'publish',
    approved: true,
    approved_by: body.approved_by ?? null,
    // Mã lệnh WordPress cấp lúc duyệt / đổi giờ. Gửi lại khi hỏi "còn đăng không?" để lần chạy cũ tự bỏ.
    dispatch_token: job.dispatch_token ?? null,
  } };
});
items.sort((a, b) => a.json.delay_seconds - b.json.delay_seconds);
console.log('[socialsync] Nhận lệnh đăng đã duyệt', JSON.stringify({ post_id: body.post_id, by: body.approved_by, jobs: items.map(i => ({ job_id: i.json.job_id, channel: i.json.channel, scheduled_at: i.json.scheduled_at, edited: i.json.content.edited_fields ?? [] })) }));
return items;

// Ngay trước khi đăng (sau khi chờ tới giờ), hỏi WordPress lượt này còn được đăng không.
// Chỉ đăng khi WordPress trả rõ ràng {go:true}. Người duyệt có thể đã Hủy lịch hoặc Đổi giờ trong Trung tâm SocialSync.
const base = $('Chờ tới giờ đăng của lượt').item.json;
const r = $json;
const http = r.statusCode ?? null;
const body = r.body && typeof r.body === 'object' ? r.body : {};
let decision = 'unconfirmed';
if (http === 200 && body.go === true) decision = 'go';
else if (http === 200 && body.go === false) decision = 'stop';
const reason = decision === 'go' ? 'ok' : (body.reason || (http ? `HTTP ${http}` : (r.error?.message || 'không gọi được WordPress')));
console.log('[socialsync] Hỏi WordPress trước khi đăng', JSON.stringify({ job_id: base.job_id, channel: base.channel, scheduled_at: base.scheduled_at, has_token: Boolean(base.dispatch_token), http, decision, reason, message: body.message ?? null }));
return { json: { ...base, go_check: { decision, reason, http, message: body.message ?? null } } };

// WordPress trả "không đăng" (đã hủy lịch / đổi giờ / bài bị gỡ) => bỏ lượt, KHÔNG báo gì (WordPress đã biết).
// WordPress không trả lời rõ ràng (lỗi mạng, sai mã bí mật, 5xx) => KHÔNG đăng cho chắc, báo lượt lỗi để người dùng bấm "Đăng lại nội dung đã duyệt".
const s = $json;
const g = s.go_check || {};
if (g.decision === 'unconfirmed') {
  console.log('[socialsync] Không xác nhận được với WordPress, không đăng', JSON.stringify({ job_id: s.job_id, channel: s.channel, reason: g.reason }));
  return { json: { ...s, report_failed: 'yes', callback: { status: 'failed', error: `Không xác nhận được với WordPress ngay trước khi đăng (${g.reason}). Chưa đăng gì lên kênh; bấm "Đăng lại nội dung đã duyệt" trong Trung tâm SocialSync.`, execution_id: $execution.id } } };
}
console.log('[socialsync] Bỏ lượt theo yêu cầu của WordPress, không đăng', JSON.stringify({ job_id: s.job_id, channel: s.channel, reason: g.reason, message: g.message }));
return { json: { ...s, report_failed: 'no' } };
